use crate::ciphers::feistel::cipher::feistel_encrypt;
use crate::ciphers::feistel::keys::feistel_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn feistel_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = feistel_default_key();
    let watch = Stopwatch::start();
    let sealed = feistel_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
